export const ANIMALS=[{name:'兔',fur:0xf7f1df,inner:0xf5adb6,kind:'rabbit'},{name:'狐',fur:0xe99747,inner:0xffd1aa,kind:'fox'},{name:'貓',fur:0xe7c77d,inner:0xf5afac,kind:'cat'},{name:'熊',fur:0x96705d,inner:0xd2a78c,kind:'bear'}];
// Canvas compatibility counterpart: same species, ears, muzzle and tail silhouette.
export function drawAnimal2D(ctx,team,x,y,size=1,angle=0){let a=ANIMALS[team],fur='#'+a.fur.toString(16).padStart(6,'0'),inner='#'+a.inner.toString(16).padStart(6,'0');ctx.save();ctx.translate(x,y);ctx.scale(size,size);const oval=(x,y,rx,ry,c)=>{ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();};let side=Math.sin(angle),back=Math.cos(angle)<-.55;for(let x of [-2.7,2.7]){if(team===0){oval(x,-7.6,1.35,4.2,fur);oval(x,-7.8,.6,2.8,inner);}else if(team===3){oval(x*1.28,-5.6,1.9,1.9,fur);oval(x*1.28,-5.6,.95,.95,inner);}else{ctx.fillStyle=fur;ctx.beginPath();ctx.moveTo(x-2,-3.7);ctx.lineTo(x,-9);ctx.lineTo(x+2,-3.7);ctx.fill();ctx.fillStyle=inner;ctx.beginPath();ctx.moveTo(x-1,-4.7);ctx.lineTo(x,-7.6);ctx.lineTo(x+1,-4.7);ctx.fill();}}oval(0,0,5.1,4.4,fur);if(!back){oval(side,-1,3.7,3.1,fur);oval(side,1.7,2.5,1.6,'#fff5df');oval(side,.9,.8,.55,'#263d36');for(let ex of [-2,2]){oval(ex+side,-.7,.52,.83,'#263d36');oval(ex+side-.15,-1,.15,.21,'#fff5df');}if(team===2){ctx.strokeStyle='#654c35';ctx.lineWidth=.45;for(let sign of [-1,1])for(let yy of [1,2]){ctx.beginPath();ctx.moveTo(sign*2.9,yy);ctx.lineTo(sign*5.8,yy-.6);ctx.stroke();}}}ctx.restore();}
